export type Label = 'A' | 'B' | 'C' | 'D';

/**
 * Identified, not positional — answers reference this id (DM-7, INV-Q-2).
 */
export type QuestionOption = {
    id: Ulid;
    questionId: Ulid;
    label: 'A' | 'B' | 'C' | 'D';
    text: string;
    /**
     * Display order; editable without invalidating answers.
     */
    position: number;
};

export type Provenance = 'generated' | 'lecturer-authored';

export type Question = {
    id: Ulid;
    sessionId: Ulid;
    /**
     * null = lecturer-authored; outlives batches and resets (INV-Q-3).
     */
    questionSetId: Ulid | null;
    /**
     * V1 rejects anything but mcq (DM-12).
     */
    kind: 'mcq' | 'short';
    prompt: string;
    options: Array<QuestionOption>;
    /**
     * An id, never an index (INV-Q-2).
     */
    correctOptionId: Ulid | null;
    provenance: 'generated' | 'lecturer-authored';
    edited: boolean;
    state: QuestionState;
    createdAt: Instant;
    orderHint: number | null;
};

/**
 * Option ids are minted server-side (INV-G-2); exactly one option carries isCorrect (INV-Q-1).
 */
export type QuestionCreate = {
    prompt: string;
    options: Array<{
        text: string;
        isCorrect: boolean;
    }>;
};

/**
 * Drafts only (G-QUESTION-MUTABLE). options, when present, is a full replacement; entries with an id keep it.
 */
export type QuestionUpdate = {
    prompt?: string;
    options?: Array<{
        id?: Ulid;
        text: string;
        isCorrect: boolean;
    }>;
};

export type Trigger = 'countdown' | 'manual';

/**
 * One generation batch (machine 2b). failed is a visible state with retry (J-2).
 */
export type QuestionSet = {
    id: Ulid;
    sessionId: Ulid;
    trigger: 'countdown' | 'manual';
    state: QuestionSetState;
    requestedAt: Instant;
    completedAt: Instant | null;
    intervalMinutesAtRequest: IntervalMinutes;
    /**
     * A-14.
     */
    requestedCount: number;
    returnedCount: number | null;
    error: string | null;
};

export type QuestionSetDetail = QuestionSet & {
    questions: Array<Question>;
};

/**
 * REST mirror of ai.countdown (machine 2a). The panel ticks locally from nextAt (INV-G-7).
 */
export type AiCountdownSnapshot = {
    state: AiCountdownState;
    remainingMs: number | null;
    nextAt: Instant | null;
    intervalMinutes: IntervalMinutes;
};

export type SetIntervalRequest = {
    intervalMinutes: IntervalMinutes;
};

/**
 * The send-to-projector act + answer-acceptance window (machine 2d, INT-3).
 */
export type QuestionPublication = {
    id: Ulid;
    questionId: Ulid;
    quizSessionId: Ulid;
    state: PublicationState;
    /**
     * The response-time zero point (INT-2).
     */
    publishedAt: Instant | null;
    /**
     * Authoritative for acceptance on BOTH sides (INV-QPUB-4).
     */
    closedAt: Instant | null;
    closeReason: PublicationCloseReason | null;
    /**
     * Exactly one true per quiz session (INV-QPUB-1).
     */
    isShowing: boolean;
    projectorState: ProjectorState;
    syncState: QuizSyncState;
};

export type PublicationWithQuestion = QuestionPublication & {
    question: Question;
    responseCount: number;
    correctCount: number;
    incorrectCount: number;
};

export type ProjectorRequest = {
    /**
     * null ⇒ withdraw to slides passthrough. A closed publication re-projects in reveal mode (Q-36).
     */
    publicationId: Ulid | null;
};

/**
 * Machine 4a device-side projection (INV-G-8) — never authority.
 */
export type QuizSessionProjection = {
    state: QuizSessionProjectionState;
    quizSessionId: Ulid | null;
    lectureSessionId: Ulid | null;
    /**
     * Encoded in the projector QR (QZ-2).
     */
    joinUrl: string | null;
    joinCode: string | null;
    joinedCount: number;
    syncState: QuizSyncState | null;
};

/**
 * Device-side read model (INV-AP-1 — replaced, never edited). Minimal PII (DM-14).
 */
export type AnswerProjection = {
    id: Ulid;
    publicationId: Ulid;
    studentIdNumber: string;
    studentDisplayName: string;
    selectedOptionId: Ulid;
    isCorrect: boolean;
    /**
     * Insight only — never affects score (INT-2).
     */
    responseTimeMs: number;
    submittedAt: Instant;
    syncedAt: Instant;
};

/**
 * Derived, never stored (INV-LB-1). points = 10 × correct (INT-2); dense ranking, ties share a rank (INV-LB-2).
 */
export type LeaderboardEntry = {
    /**
     * The key (QZ-3).
     */
    studentIdNumber: string;
    /**
     * Panel only — never projected (INV-LB-3).
     */
    displayName: string;
    answered: number;
    correct: number;
    points: number;
    /**
     * correct/answered; 0 when answered = 0 (INV-QP-2).
     */
    accuracy: number;
    avgResponseMs: number;
    rank: number;
};

export type Leaderboard = {
    sessionId: Ulid;
    entries: Array<LeaderboardEntry>;
    computedAt: Instant;
    /**
     * Machine 4d ≥ stale (INV-AP-2).
     */
    stale: boolean;
};

export type QuizSessionCreateRequest = {
    lectureSessionId: Ulid;
    deviceId: Ulid;
    hallDisplayName: string;
};

export type QuizSessionCreateResponse = {
    id: Ulid;
    lectureSessionId: Ulid;
    state: 'open' | 'closed';
    joinCode: string;
    /**
     * Quiz-service owns its URL namespace (DM-15).
     */
    joinUrl: string;
    openedAt: Instant;
};

/**
 * Server-to-server only — carries correctness so quiz-service evaluates at submit time (Z-22). Students never see it before close.
 */
export type PublicationPush = {
    publicationId: Ulid;
    quizSessionId: Ulid;
    questionId: Ulid;
    prompt: string;
    options: Array<{
        id: Ulid;
        label: 'A' | 'B' | 'C' | 'D';
        text: string;
    }>;
    correctOptionId: Ulid;
    publishedAt: Instant;
};

export type PublicationCloseRequest = {
    publicationId: Ulid;
    /**
     * Authoritative for acceptance on both sides (INV-QPUB-4); no grace window (SM-Q-6).
     */
    closedAt: Instant;
    closeReason: PublicationCloseReason;
};

export type Service = 'core-api' | 'pipeline-manager' | 'ai' | 'deploy' | 'quiz-sync';

/**
 * AD-7 row. Append-only (INV-LE-1); context never contains secrets (INV-ST-1).
 */
export type LogEntry = {
    id: Ulid;
    at: Instant;
    level: LogLevel;
    category: LogCategory;
    service: 'core-api' | 'pipeline-manager' | 'ai' | 'deploy' | 'quiz-sync';
    message: string;
    context: {
        [key: string]: unknown;
    } | null;
    sessionId: Ulid | null;
    userId: Ulid | null;
};

export type Severity = 'info' | 'warning' | 'error' | 'critical';

/**
 * A current condition, distinct from the log (INV-SA-2). Cannot be cleared while still true (INV-SA-1).
 */
export type SystemAlert = {
    id: Ulid;
    /**
     * Stable machine code, e.g. storage.critical, capture-card.absent.
     */
    code: string;
    severity: 'info' | 'warning' | 'error' | 'critical';
    category: LogCategory;
    /**
     * Plain language for a non-technical lecturer.
     */
    title: string;
    detail: string | null;
    raisedAt: Instant;
    clearedAt: Instant | null;
    clearedReason: 'resolved' | 'acknowledged' | 'superseded' | null;
    acknowledgedBy: Ulid | null;
    context: {
        [key: string]: unknown;
    } | null;
    relatedEntity: {
        type: string;
        id: string;
    } | null;
};

